#include "ADC.h"
#include "telemetry.h"
#include "systick.h"
#include "ring_buffer.h"

uint16_t raw =  0;
int main(void)
{
	// Hardware Initializations
    adc_init();
    systick_init_ms(16000000);
    telemetry_init(600000);

    /* Start the conversion */
    ADC_conversion();

    /* TURN GREEN LED (PD12) ON FIRST */
    GPIOD->BSRR = (1U << 12);

    while (1)
    {
    	// Read The Accumulate
        raw = ADC_read();
        telemetry_feed_sample(raw);

        // Process window threshold
        telemetry_process();

        // Pace Acquisition
        systick_delay(100);
    }

    return 0;
}
